  flav = flav || 'terminal';
  var inner = rec[flav] || rec.neon || rec.terminal || rec.bit;
  var s = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  s.setAttribute('viewBox', '0 0 64 64');
